function rotateLeft(list, k) {
  var shift = k;
  return list.slice(shift).concat(list.slice(0, shift));
}

console.log(rotateLeft([1, 2, 3, 4, 5], 7));

solution.code:
function rotateLeft(list, k) {
  var shift = k % list.length;
  return list.slice(shift).concat(list.slice(0, shift));
}

console.log(rotateLeft([1, 2, 3, 4, 5], 7));
